<?php
declare(strict_types=1);
require __DIR__.'/harness.php';require __DIR__.'/database.php';require __DIR__.'/services-fixture.php';
use Hostider\Core\Database\Migrator;use Hostider\Core\Id;use Hostider\Core\Http\HttpError;use Hostider\Core\Security\{AccessGrant,Principal};use Hostider\Services\{Engine,Worker,Policies,Renewals};use Hostider\Hosting\Pools;
$db=integrationDb();(new Migrator($db,dirname(__DIR__).'/migrations'))->migrate();
function lifecycleFixture($db,bool $manual=false): array
{
    $f=serviceFixture($db,1,$manual);$pool=(new Pools($db,$f['config']))->configure($f['product']);$engine=new Engine($db,$f['config']);$id=$engine->discover($f['order']['id'],$f['actor'],Id::uuid())[0];$permissions=['services.approve','services.renew','services.policy','services.cancel','services.suspend','services.unsuspend','services.terminate'];$grants=[];foreach($permissions as $permission){$grants[]=new AccessGrant($permission,[$f['customer']],[$id]);}$staff=new Principal('lifecycle-staff',$permissions,staff:true,mfa:true,expiresAt:time()+3600,verifiedAt:time(),grants:$grants,administrative:true);$policies=new Policies($db,$f['config']);$renewals=new Renewals($db,$f['config']);return $f+compact('pool','engine','id','staff','policies','renewals');
}
function activateLifecycle($db,array $f): void
{
    if($f['line']['activation_policy']==='MANUAL'){$f['engine']->approve($f['id'],$f['customer'],$f['staff'],Id::uuid());}$operation=$f['engine']->repository->find($f['id'],lock:false)['current_operation_id'];same(true,(new Worker($db,$f['config']))->once($f['actor'],$operation));
}
test('F3-E explicit policy inheritance keeps missing decisions closed and optimistic updates scoped',function()use($db): void{
    $f=lifecycleFixture($db);$s=$f['engine']->repository->find($f['id'],lock:false);same(null,$f['policies']->resolve($s)['grace_seconds']);same(409,raises(HttpError::class,fn()=>Policies::required($f['policies']->resolve($s),'grace_seconds'))->status);
    $db->transaction(fn()=>$f['policies']->set('PRODUCT',$f['product'],['grace_seconds'=>600,'price_protected'=>false,'price_notice_required'=>false],0,$f['staff']));$db->transaction(fn()=>$f['policies']->set('SERVICE',$f['id'],['grace_seconds'=>null,'auto_suspend'=>true],0,$f['staff']));same(600,$f['policies']->resolve($s)['grace_seconds']);same(true,$f['policies']->resolve($s)['auto_suspend']);same(409,raises(HttpError::class,fn()=>$db->transaction(fn()=>$f['policies']->set('SERVICE',$f['id'],[],0,$f['staff'])))->status);
});
test('F3-E paid manual service remains held until scoped approval then provisions once',function()use($db): void{
    $f=lifecycleFixture($db,true);same('PENDING_APPROVAL',$f['engine']->repository->find($f['id'],lock:false)['status']);same(401,raises(HttpError::class,fn()=>$f['engine']->approve($f['id'],$f['customer'],$f['actor'],Id::uuid()))->status);activateLifecycle($db,$f);same('ACTIVE',$f['engine']->repository->find($f['id'],lock:false)['status']);same(409,raises(HttpError::class,fn()=>$f['engine']->approve($f['id'],$f['customer'],$f['staff'],Id::uuid()))->status);same(1,(int)$db->execute('SELECT COUNT(*) FROM svc_approvals WHERE service_id=?',[$f['id']])->fetchColumn());
});
test('F3-E renewal creates independent fixed bill and pending period but never a new service',function()use($db): void{
    $f=lifecycleFixture($db);activateLifecycle($db,$f);$db->transaction(fn()=>$f['policies']->set('SERVICE',$f['id'],['price_protected'=>false,'price_notice_required'=>false],0,$f['staff']));$before=$f['engine']->repository->find($f['id'],lock:false)['current_period_id'];$renewal=$f['renewals']->request($f['id'],$f['customer'],$f['staff'],Id::uuid(),$f['now']);same('AWAITING_PAYMENT',$renewal['status']);same($renewal['id'],$f['renewals']->request($f['id'],$f['customer'],$f['staff'],Id::uuid(),$f['now'])['id']);same($before,$f['engine']->repository->find($f['id'],lock:false)['current_period_id']);same(409,raises(HttpError::class,fn()=>$f['engine']->discover($renewal['order_id'],$f['actor'],Id::uuid()))->status);same(409,raises(HttpError::class,fn()=>$f['renewals']->autoFund($renewal['id'],$f['staff'],Id::uuid()))->status);
    $f['renewals']->walletOptIn($f['id'],$f['customer'],true,$f['staff'],Id::uuid());$order=$f['orders']->repository->find($renewal['order_id'],$f['customer']);$bill=$f['billing']->detail($order['payment_request_id'],$f['customer']);$money=new \Hostider\Finance\Money($bill['total_minor'],new \Hostider\Finance\Currency($bill['currency']));$db->transaction(function()use($f,$money): void{$payment=$f['finance']->recordTestCollection($f['customer'],$money,Id::uuid(),$f['actor'],Id::uuid());$f['finance']->creditWallet($f['customer'],$payment,$money,Id::uuid(),$f['actor'],Id::uuid());});$f['renewals']->autoFund($renewal['id'],$f['staff'],Id::uuid());$f['renewals']->autoFund($renewal['id'],$f['staff'],Id::uuid());same('PAID',$f['billing']->detail($order['payment_request_id'],$f['customer'])['status']);same($before,$f['engine']->repository->find($f['id'],lock:false)['current_period_id']);same('0',$f['finance']->repository->balance($f['finance']->repository->wallet($f['customer'],false)['id']));
});
test('F3-E payment alone never advances period; independent provider renewal verifies next period once',function()use($db): void{
    $f=lifecycleFixture($db);activateLifecycle($db,$f);$db->transaction(fn()=>$f['policies']->set('SERVICE',$f['id'],['price_protected'=>false,'price_notice_required'=>false],0,$f['staff']));$previous=$f['engine']->repository->find($f['id'],lock:false)['current_period_id'];$renewal=$f['renewals']->request($f['id'],$f['customer'],$f['staff'],Id::uuid(),$f['now']);same(409,raises(HttpError::class,fn()=>$f['renewals']->preparePaid($renewal['id'],$f['staff'],Id::uuid()))->status);$order=$f['orders']->repository->find($renewal['order_id'],$f['customer']);$bill=$f['billing']->detail($order['payment_request_id'],$f['customer']);$money=new \Hostider\Finance\Money($bill['total_minor'],new \Hostider\Finance\Currency($bill['currency']));$db->transaction(function()use($f,$order,$money): void{$payment=$f['finance']->recordTestCollection($f['customer'],$money,Id::uuid(),$f['actor'],Id::uuid());$f['orders']->fund($order['id'],$f['customer'],$money,'COLLECTION',$payment,Id::uuid(),$f['actor'],Id::uuid());});same($previous,$f['engine']->repository->find($f['id'],lock:false)['current_period_id']);$operation=$f['renewals']->preparePaid($renewal['id'],$f['staff'],Id::uuid());$before=$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn();$worker=new \Hostider\Services\RenewalWorker($db,$f['config']);same(true,$worker->once($operation,$f['actor']));same(false,$worker->once($operation,$f['actor']));same($renewal['period_id'],$f['engine']->repository->find($f['id'],lock:false)['current_period_id']);same($before,$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn());same('VERIFIED',$db->execute('SELECT status FROM svc_periods WHERE id=?',[$renewal['period_id']])->fetchColumn());same(1,(int)$db->execute('SELECT COUNT(*) FROM mock_hosting_accounts WHERE service_id=?',[$f['id']])->fetchColumn());
});
test('F3-E suspend unsuspend and cancellation reversal require independent provider state',function()use($db): void{
    $f=lifecycleFixture($db);activateLifecycle($db,$f);$actions=new \Hostider\Services\Actions($db,$f['config']);$worker=new \Hostider\Services\ActionWorker($db,$f['config']);$before=$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn();$operation=$actions->request($f['id'],$f['customer'],'SUSPEND',$f['staff'],Id::uuid());same(409,raises(HttpError::class,fn()=>$actions->request($f['id'],$f['customer'],'SUSPEND',$f['staff'],Id::uuid()))->status);same(true,$worker->once($operation,$f['actor']));same('SUSPENDED',$f['engine']->repository->find($f['id'],lock:false)['status']);$operation=$actions->request($f['id'],$f['customer'],'UNSUSPEND',$f['staff'],Id::uuid());same(true,$worker->once($operation,$f['actor']));same('ACTIVE',$f['engine']->repository->find($f['id'],lock:false)['status']);$db->transaction(fn()=>$f['policies']->set('SERVICE',$f['id'],['allow_cancel'=>true,'termination_wait_seconds'=>5],0,$f['staff']));$actions->scheduleCancel($f['id'],$f['customer'],$f['staff'],Id::uuid());same('CANCEL_SCHEDULED',$f['engine']->repository->find($f['id'],lock:false)['status']);same(409,raises(HttpError::class,fn()=>$actions->request($f['id'],$f['customer'],'TERMINATE',$f['staff'],Id::uuid(),true))->status);$actions->undoCancel($f['id'],$f['customer'],$f['staff'],Id::uuid());same('ACTIVE',$f['engine']->repository->find($f['id'],lock:false)['status']);same($before,$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn());
});
test('F3-E termination waits for immutable cancellation deadline and never resurrects resource',function()use($db): void{
    $f=lifecycleFixture($db);activateLifecycle($db,$f);$actions=new \Hostider\Services\Actions($db,$f['config']);$db->transaction(fn()=>$f['policies']->set('SERVICE',$f['id'],['allow_cancel'=>true,'termination_wait_seconds'=>5],0,$f['staff']));$cancel=$actions->scheduleCancel($f['id'],$f['customer'],$f['staff'],Id::uuid());$deadline=$db->execute('SELECT UNIX_TIMESTAMP(execute_after) FROM svc_cancellations WHERE id=?',[$cancel['cancellation_id']])->fetchColumn();raises(PDOException::class,fn()=>$db->execute('UPDATE svc_cancellations SET execute_after=UTC_TIMESTAMP(6) WHERE id=?',[$cancel['cancellation_id']]));
    // Advance only this isolated MariaDB session clock; no real provider, host clock or production data changes.
    $db->execute('SET timestamp='.((int)$deadline+1));try{same(409,raises(HttpError::class,fn()=>$actions->request($f['id'],$f['customer'],'TERMINATE',$f['staff'],Id::uuid(),false))->status);$operation=$actions->request($f['id'],$f['customer'],'TERMINATE',$f['staff'],Id::uuid(),true);same(true,(new \Hostider\Services\ActionWorker($db,$f['config']))->once($operation,$f['actor']));same('TERMINATED',$f['engine']->repository->find($f['id'],lock:false)['status']);same(409,raises(HttpError::class,fn()=>$actions->request($f['id'],$f['customer'],'UNSUSPEND',$f['staff'],Id::uuid()))->status);same('RELEASED',$db->execute('SELECT status FROM hosting_reservations WHERE service_id=?',[$f['id']])->fetchColumn());}finally{$db->execute('SET timestamp=0');}
});
test('F3-E grace scheduler holds one notice and queues one suspend only after explicit grace',function()use($db): void{
    $f=lifecycleFixture($db);activateLifecycle($db,$f);$db->transaction(fn()=>$f['policies']->set('SERVICE',$f['id'],['auto_suspend'=>true,'grace_seconds'=>120],0,$f['staff']));$service=$f['engine']->repository->find($f['id'],lock:false);$end=(int)$db->execute('SELECT UNIX_TIMESTAMP(ends_at) FROM svc_periods WHERE id=?',[$service['current_period_id']])->fetchColumn();$scheduler=new \Hostider\Services\Scheduler($db,$f['config']);
    $db->execute('SET timestamp='.($end+60));try{$scheduler->run();same(0,(int)$db->execute("SELECT COUNT(*) FROM svc_operations WHERE service_id=? AND kind='SUSPEND'",[$f['id']])->fetchColumn());$db->execute('SET timestamp='.($end+121));$scheduler->run();$scheduler->run();same(1,(int)$db->execute("SELECT COUNT(*) FROM svc_operations WHERE service_id=? AND kind='SUSPEND'",[$f['id']])->fetchColumn());same(1,(int)$db->execute("SELECT COUNT(*) FROM svc_notices WHERE service_id=? AND kind='PAYMENT_OR_RENEWAL_OVERDUE' AND status='HELD'",[$f['id']])->fetchColumn());$operation=$f['engine']->repository->find($f['id'],lock:false)['current_operation_id'];same(true,(new \Hostider\Services\Runner($db,$f['config']))->once($f['actor'],$operation));same('SUSPENDED',$f['engine']->repository->find($f['id'],lock:false)['status']);}finally{$db->execute('SET timestamp=0');}
});
test('F3-E independent cron process exits on an existing scheduler lease',function()use($db): void{
    require_once __DIR__.'/support/FixtureDirectory.php';$f=lifecycleFixture($db);$scheduler=new \Hostider\Services\Scheduler($db,$f['config']);$directory=dirname(__DIR__).'/storage/service-test-'.bin2hex(random_bytes(8));mkdir($directory,0700,true);$file=$directory.'/fixture.json';file_put_contents($file,json_encode(['key'=>$f['config']->key,'order'=>$f['order']['id']],JSON_THROW_ON_ERROR));same(1,(int)$db->execute('SELECT GET_LOCK(?,0)',[$scheduler->lockName()])->fetchColumn());
    try{$pipes=[];$p=proc_open([PHP_BINARY,__DIR__.'/services-child.php',$file,'schedule'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($p)){throw new RuntimeException('Child unavailable');}fclose($pipes[0]);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(0,proc_close($p));same('',$err);same(true,json_decode($out,true,32,JSON_THROW_ON_ERROR)['overlap']);}finally{$db->execute('SELECT RELEASE_LOCK(?)',[$scheduler->lockName()]);FixtureDirectory::remove($directory);}
});
runTests();
